function Cash({profile}:{profile:Profile}){const [reg,setReg]=useState<any>(null),[rows,setRows]=useState<any[]>([]),[amount,setAmount]=useState(""),[type,setType]=useState("ingreso"),[concept,setConcept]=useState(""),[method,setMethod]=useState("efectivo"),[error,setError]=useState("");async function load(){const [a,b]=await Promise.all([sb.from("cash_registers").select("*").eq("seller_id",profile.id).eq("status","abierta").maybeSingle(),sb.from("cash_movements").select("*").eq("created_by",profile.id).order("created_at",{ascending:false})]);setReg(a.data);if(b.error)setError(errText(b.error));else setRows(b.data||[])}useEffect(()=>{load()},[]);const balance=Number(reg?.opening_amount||0)+rows.reduce((n,r)=>n+(r.type==="ingreso"?Number(r.amount):-Number(r.amount)),0);async function openCash(){const {error}=await sb.from("cash_registers").insert({seller_id:profile.id,opening_amount:Number(amount||0)});if(error)setError(errText(error));else{setAmount("");load()}}async function move(){const {error}=await sb.from("cash_movements").insert({register_id:reg.id,type,concept,amount:Number(amount),payment_method:method,created_by:profile.id});if(error)setError(errText(error));else{setAmount("");setConcept("");load()}}async function closeCash(){const counted=prompt("Arqueo final (Gs.):");if(counted===null)return;const {error}=await sb.from("cash_registers").update({status:"cerrada",closed_at:new Date().toISOString(),counted_amount:Number(counted)}).eq("id",reg.id);if(error)setError(errText(error));else load()}return <><Header title="Caja" description="Apertura, movimientos y cierre de caja." onRefresh={load}/>{!reg?<div className="panel"><h3>Abrir caja</h3><Field label="Monto inicial"><input type="number" min="0" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><button className="btn" onClick={openCash}>Abrir caja</button></div>:<><div className="grid three"><div className="card"><div className="kicker">Saldo</div><div className="metric">{money(balance)}</div></div><div className="card"><div className="kicker">Apertura</div><div className="metric">{money(reg.opening_amount)}</div></div><div className="card"><div className="kicker">Estado</div><div className="metric">Abierta</div></div></div><div className="panel"><div className="subhead"><h3>Registrar movimiento</h3><button className="btn secondary" onClick={closeCash}>Cerrar / arqueo</button></div><div className="formgrid"><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value)}><option>ingreso</option><option>egreso</option></select></Field><Field label="Monto"><input type="number" min="0" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field label="Método"><select value={method} onChange={e=>setMethod(e.target.value)}>{["efectivo","transferencia","tarjeta","qr","otro"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Concepto"><input value={concept} onChange={e=>setConcept(e.target.value)}/></Field></div><button className="btn" disabled={!amount||!concept} onClick={move}>Registrar movimiento</button></div><div className="panel"><div className="tablewrap"><table className="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Concepto</th><th>Método</th><th>Monto</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{date(r.created_at)}</td><td><Status>{r.type}</Status></td><td>{r.concept}</td><td>{r.payment_method||"—"}</td><td>{money(r.amount)}</td></tr>)}</tbody></table></div></div></>}{error&&<div className="error">{error}</div>}</>}
function Reports(){const [d,setD]=useState<any>({sales:[],quotes:[],payments:[],orders:[],clients:[]});const [error,setError]=useState("");useEffect(()=>{(async()=>{const [s,q,p,o,c]=await Promise.all([sb.from("sales").select("total,balance,created_at"),sb.from("quotes").select("total,status,created_at"),sb.from("payments").select("amount,paid_at"),sb.from("orders").select("status,priority"),sb.from("clients").select("active")]);if([s,q,p,o,c].some(x=>x.error))setError("No se pudieron cargar todos los indicadores.");setD({sales:s.data||[],quotes:q.data||[],payments:p.data||[],orders:o.data||[],clients:c.data||[]})})()},[]);const sales=d.sales.reduce((n:number,r:any)=>n+Number(r.total||0),0);const paid=d.payments.reduce((n:number,r:any)=>n+Number(r.amount||0),0);return <><Header title="Reportes" description="Indicadores operativos y financieros sobre datos reales."/><div className="grid"><div className="card"><div className="kicker">Ventas</div><div className="metric">{money(sales)}</div></div><div className="card"><div className="kicker">Cobros</div><div className="metric">{money(paid)}</div></div><div className="card"><div className="kicker">Pedidos pendientes</div><div className="metric">{d.orders.filter((x:any)=>!['entregado','cancelado'].includes(x.status)).length}</div></div><div className="card"><div className="kicker">Clientes activos</div><div className="metric">{d.clients.filter((x:any)=>x.active).length}</div></div></div><div className="grid three"><div className="panel"><h3>Presupuestos</h3>{["borrador","enviado","modificacion","aprobado","rechazado","vencido"].map(x=><p className="reportrow" key={x}><span>{x}</span><strong>{d.quotes.filter((q:any)=>q.status===x).length}</strong></p>)}</div><div className="panel"><h3>Ventas</h3><p className="reportrow"><span>Con saldo</span><strong>{d.sales.filter((s:any)=>Number(s.balance)>0).length}</strong></p><p className="reportrow"><span>Pagadas</span><strong>{d.sales.filter((s:any)=>Number(s.balance)<=0).length}</strong></p></div><div className="panel"><h3>Prioridades</h3>{["normal","alta","urgente"].map(x=><p className="reportrow" key={x}><span>{x}</span><strong>{d.orders.filter((o:any)=>o.priority===x).length}</strong></p>)}</div></div>{error&&<div className="error">{error}</div>}</>}
function QrReader(){const [code,setCode]=useState(new URLSearchParams(location.search).get("code")||"");const [data,setData]=useState<any>(null);const [error,setError]=useState("");const [scan,setScan]=useState(false);async function lookup(v=code){setData(null);setError("");const value=v.trim().toUpperCase();if(!/^(PRE-|VENT-|PED-)/.test(value)){setError("Código no reconocido.");return}const table=value.startsWith("PRE-")?"quotes":value.startsWith("VENT-")?"sales":"orders";const {data,error}=await sb.from(table).select("*").or(`code.eq.${value},number.eq.${value}`).maybeSingle();if(error||!data){setError("No se encontró el registro o no tienes acceso.");return}setData({table,row:data})}async function camera(){setScan(true);try{const {Html5Qrcode}=await import("html5-qrcode");const q=new Html5Qrcode("qr-reader");await q.start({facingMode:"environment"},{fps:10,qrbox:220},async text=>{setCode(text);await q.stop();setScan(false);lookup(text)},()=>{})}catch{setScan(false);setError("No fue posible iniciar la cámara.")}}return <><Header title="Lector QR" description="Consulta segura de presupuestos, ventas y pedidos."/><div className="qrbox"><Field label="Código"><input value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/></Field><div className="actions"><button className="btn" onClick={()=>lookup()}><Search size={16}/>Consultar</button><button className="btn secondary" onClick={camera}><Camera size={16}/>Cámara</button></div><div id="qr-reader" className="scanner">{!scan&&<div className="scannerhint"><QrCode size={34}/><span>{scan?"Escaneando…":"Cámara QR"}</span></div>}</div>{error&&<div className="error">{error}</div>}{data&&<div className="panel"><h3>{data.row.code}</h3>{data.table==="quotes"?<><p>Estado: <Status>{data.row.status}</Status></p><p>Total: <strong>{money(data.row.total)}</strong></p><p>Válido hasta: {date(data.row.valid_until)}</p></>:data.table==="sales"?<><p>Pago: <Status>{data.row.payment_status}</Status></p><p>Total: <strong>{money(data.row.total)}</strong></p><p>Saldo: <strong>{money(data.row.balance)}</strong></p></>:<><p>Prioridad: <Status>{data.row.priority}</Status></p><p>Estado: <Status>{data.row.status}</Status></p><p>Entrega: {date(data.row.delivery_date)} {data.row.delivery_time||""}</p></>}</div>}</div></>}
function Users(){const [rows,setRows]=useState<any[]>([]),[rolesList,setRolesList]=useState<any[]>([]),[open,setOpen]=useState(false),[name,setName]=useState(""),[email,setEmail]=useState(""),[role,setRole]=useState(""),[error,setError]=useState("");async function load(){const [a,b]=await Promise.all([sb.from("profiles").select("*,role:roles(name)").order("created_at",{ascending:false}),sb.from("roles").select("id,name").order("name")]);if(a.error)setError(errText(a.error));else setRows(a.data||[]);if(!b.error)setRolesList(b.data||[])}useEffect(()=>{load()},[]);async function create(){const {data,error}=await sb.functions.invoke("admin-users",{body:{action:"create",email,full_name:name,role_id:role}});if(error||data?.error)setError(errText(error||data?.error));else{setOpen(false);await load()}}async function change(id:string,action:string,value:string){const {data,error}=await sb.functions.invoke("admin-users",{body:{action,user_id:id,value}});if(error||data?.error)setError(errText(error||data?.error));else load()}return <><Header title="Usuarios" description="Usuarios, roles, activación y acceso seguro." onNew={()=>setOpen(true)} onRefresh={load}/><div className="panel"><div className="tablewrap"><table className="table"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><strong>{r.full_name||"Sin nombre"}</strong><br/><span className="muted">{r.email}</span></td><td><select className="compact" value={r.role_id||""} onChange={e=>change(r.id,"set_role",e.target.value)}>{rolesList.map(x=><option key={x.id} value={x.id}>{roles[x.name]||x.name}</option>)}</select></td><td><Status>{r.status}</Status></td><td><button className="btn secondary smallbtn" onClick={()=>change(r.id,"set_status",r.status==='activo'?'inactivo':'activo')}>{r.status==='activo'?"Desactivar":"Activar"}</button></td></tr>)}</tbody></table></div></div>{error&&<div className="error">{error}</div>}{open&&<Modal title="Invitar usuario" onClose={()=>setOpen(false)}><div className="formgrid"><Field label="Nombre"><input value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Correo"><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Rol"><select value={role} onChange={e=>setRole(e.target.value)}><option value="">Seleccionar…</option>{rolesList.map(x=><option key={x.id} value={x.id}>{roles[x.name]||x.name}</option>)}</select></Field></div><p className="muted small">El usuario recibe una invitación y define su propia contraseña.</p><div className="modalfoot"><button className="btn secondary" onClick={()=>setOpen(false)}>Cancelar</button><button className="btn" disabled={!email||!role} onClick={create}>Enviar invitación</button></div></Modal>}</>}
function Settings(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{(async()=>{const {data}=await sb.from("system_settings").select("*").order("key");setRows(data||[])})()},[]);const company=rows.find(x=>x.key==="company")?.value||{};return <><Header title="Configuración" description="Moneda, IVA y datos corporativos."/><div className="panel"><h3>Parámetros</h3><div className="settinggrid"><div className="setting"><strong>Moneda</strong><span>PYG / Gs.</span></div><div className="setting"><strong>IVA</strong><span>10%</span></div><div className="setting"><strong>Precios</strong><span>Sin IVA</span></div></div></div><div className="panel"><h3>Empresa</h3><div className="companydata">{Object.entries(company).map(([k,v])=><div key={k}><span>{k}</span><strong>{String(v)}</strong></div>)}</div></div></>}
function Audit(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{(async()=>{const {data}=await sb.from("audit_logs").select("*,profiles(full_name,email)").order("created_at",{ascending:false}).limit(500);setRows(data||[])})()},[]);return <><Header title="Auditoría" description="Historial de operaciones del sistema."/><div className="panel"><div className="tablewrap"><table className="table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>ID</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{new Date(r.created_at).toLocaleString("es-PY")}</td><td>{r.profiles?.full_name||r.profiles?.email||"Sistema"}</td><td><Status>{r.action}</Status></td><td>{r.entity}</td><td><code>{r.entity_id||"—"}</code></td></tr>)}</tbody></table></div></div></>}
